SELECT (SELECT id FROM public.import_runs WHERE pipeline_version = 'vision-quality-gated-batch-0459-0463-v1' ORDER BY started_at DESC LIMIT 1), b.id, 463, 'educational'::page_kind, 'বাংলাদেশের গণমাধ্যম বাংলাদেশ টেলিভিশন স্থাপিত হয়- ১৯৬৪ সালে। প্রথম স্থাপন করা হয়- ডিআইটি ভবনে। ডিআইটি ভবনের বর্তমান নাম- রাজউক ভবন। রামপুরা টিভি কেন্দ্র চালু হয়- ১৯৭৫ সালে। প্রথম নাটক- একতলা-দোতলা (১৯৬৫)। প্রথম সঙ্গীত শিল্পী- ফেরদৌসী রহমান। বি টি ভি বাংলাদেশে রঙিন টেলিভিশন চালু হয় ১৯৮০ সালে। তার ও টেলিফোন ব্যবস্থা বাংলাদেশে ইন্টারনেট ব্যবস্থা চালু হয়- ১৯৯৬ সালে। বাংলাদেশে সর্বপ্রথম কার্ডফোন ব্যবস্থা চালু হয়- ১৯৯২ সালে। ভি স্যাট- বহির্বিশ্বের সাথে ডাটা আদান-প্রদানের মাধ্যম। বিটিআরসি- বাংলাদেশ টেলিকম রেগুলেটরি কমিশন। বাংলাদেশ টেলিগ্রাফ ও টেলিফোন (টিএন্ডটি) বোর্ডের সদর দপ্তর অবস্থিত- ঢাকা। বাংলাদেশে সর্বপ্রথম ডিজিটাল টেলিফোন ব্যবস্থা চালু হয়- ১৯৯০ সালে। বাংলাদেশের কম্পিউটারে প্রথম বাংলা ফন্ট ব্যবহৃত হয়- ১৯৮৭ সালে (নাম- বিজয়)। বাংলাদেশের প্রথম সেলুলার ফোন- সিটিসেল (চালু হয়-১৯৯৩ সালে)। পৃথিবীর যে দেশটির সাথে বাংলাদেশের টেলিযোগাযোগ নেই- ইসরাইল। বাংলাদেশের সরকারি টেলিভিশন- ৪টি (উপকেন্দ্র- ১৪টি, পুনঃপ্রচার কেন্দ্র- ১টি, রাঙ্গামাটি)। বাংলাদেশের প্রথম বাংলা ডিজিটাল স্যাটেলাইট চ্যানেল- চ্যানেল আই (১৯৯৭)। বাংলাদেশ বেতার বাংলাদেশ বেতারের পূর্বনাম- রেডিও বাংলাদেশ। স্থাপিত হয়- ১৯৩৯ সালে। সর্বপ্রথম স্বাধীন বাংলা বেতার কেন্দ্র স্থাপিত হয়েছিল- চট্টগ্রামের কালুরঘাটে। বর্তমান বাংলাদেশ বেতারের সদর দপ্তর অবস্থিত- ঢাকার আগারগাঁও। বাংলাদেশের প্রথম বেসরকারি রেডিও চ্যানেল- রেডিও মেট্রোওয়েভ। বাংলাদেশে প্রথম বেসরকারি টেলিভিশন চ্যানেল- এটিএন বাংলা (১৯৯৭ সালে)। বাংলাদেশে ''ডিস এন্টিনা'' ব্যবহার চালু হয়- ১৯৯২ সালে। Zubair''s GK - ৪০৬', 'বাংলাদেশের গণমাধ্যম', 'বাংলাদেশের গণমাধ্যম', 'high'::confidence_level, 'vision_ocr_with_image_grounded_review', 'gemini-3-flash-preview', 'Quality-gated batch: source-preserving OCR, correction log, semantic tagging, and external-verification ledger recorded.', '{"source_image_sha256":"2fb4ecf7bbf9689bc194d1d5995b764b5772774f77ebc0ca1a3d276f9da8afb2","extraction_model":"gemini-3-flash-